  "content": "1|import { randomUUID } from 'crypto';
2|import type { AssistantRequestRouting } from '../../../shared/api/contracts/ai/appendooGateway.types';
3|import type { AgentMode } from '../../../shared/api/contracts/ai/agentTypes';
4|
5|/**
6| * V5 Phase P02 § 17 — `TaskContract`.
7| *
8| * "conceptual removal: routing result = understanding" → "replacement: routing result = signal,
9| * TaskContract = normalized engineering contract". `resolveTaskContract` treats the existing,
10| * already-production-reachable `routeAssistantRequest()` output (`AssistantRequestRouting` —
11| * `src/server/domain/ai/assistantRequestRouter.ts`) as exactly that: a SIGNAL it consumes, not
12| * something it re-implements. `requiresClarification`, `requestClass`, `confidence`, and
13| * `routingReason` all come from the real router; `resolveTaskContract` normalizes them into the
14| * doc's canonical contract shape and adds the (today: single, derived) acceptance criterion.
15| *
16| * Scoped subset: the full doc shape also includes `explicitConstraints`/`inferredConstraints`,
17| * multi-item `requestedOutcomes`, and `approvalPolicy` as a rich ref. Those require either NLU
18| * extraction (no live model — EV-3) or an approval-policy registry that doesn't exist yet, so
19| * they're intentionally minimal/deferred rather than fabricated — see PHASE-EVIDENCE-REPORT-P02.md.
20| */
21|export type TaskClass =
22|  | 'ENGINEERING_CHANGE'
23|  | 'ENGINEERING_QUERY'
24|  | 'OPERATIONAL_ACTION'
25|  | 'GENERAL_CHAT';
26|
27|export type AcceptanceCriterion = {
28|  criterionId: string;
29|  statement: string;
30|  required: boolean;
31|};
32|
33|export type AmbiguityAssessment = {
34|  isAmbiguous: boolean;
35|  reason?: string;
36|};
37|
38|export type TaskContract = {
39|  taskContractId: string;
40|  revision: number;
41|  taskId: string;
42|
43|  rawUserRequest: string;
44|  normalizedObjective: string;
45|
46|  taskClass: TaskClass;
47|  acceptanceCriteria: AcceptanceCriterion[];
48|
49|  mutationExpectation: 'EXPECTED' | 'POSSIBLE' | 'NOT_EXPECTED' | 'UNKNOWN';
50|
51|  ambiguity: AmbiguityAssessment;
52|
53|  sourceRefs: string[];
54|  createdAt: string;
55|};
56|
57|const mapRequestClassToTaskClass = (
58|  requestClass: AssistantRequestRouting['requestClass'],
59|): TaskClass => {
60|  switch (requestClass) {
61|    case 'ENGINEERING_CHANGE':
62|      return 'ENGINEERING_CHANGE';
63|    case 'ENGINEERING_QUERY':
64|    case 'CONTEXT_QUERY':
65|      return 'ENGINEERING_QUERY';
66|    case 'OPERATIONAL_ACTION':
67|      return 'OPERATIONAL_ACTION';
68|    case 'TOOL_QUERY':
69|      return 'ENGINEERING_QUERY';
70|    default:
71|      return 'GENERAL_CHAT';
72|  }
73|};
74|
75|const resolveMutationExpectation = (taskClass: TaskClass): TaskContract['mutationExpectation'] => {
76|  switch (taskClass) {
77|    case 'ENGINEERING_CHANGE':
78|      return 'EXPECTED';
79|    case 'OPERATIONAL_ACTION':
80|      return 'POSSIBLE';
81|    case 'ENGINEERING_QUERY':
82|    case 'GENERAL_CHAT':
83|      return 'NOT_EXPECTED';
84|    default:
85|      return 'UNKNOWN';
86|  }
87|};
88|
89|const buildAcceptanceCriteria = (taskClass: TaskClass): AcceptanceCriterion[] => {
90|  if (taskClass !== 'ENGINEERING_CHANGE') {
91|    return [];
92|  }
93|  return [{
94|    criterionId: randomUUID(),
95|    statement: 'The final proposal must pass proposal validation (validateProposal ok:true).',
96|    required: true,
97|  }];
98|};
99|
100|/**
101| * `routing`/`mode` are the only real, already-available signals at every current call site
102| * (`AiManager.processAgentRun`, and by extension `AgentOrchestrator.run()` when no richer
103| * routing was passed). When `routing` is omitted (e.g. a caller/test that doesn't route through
104| * `routeAssistantRequest` first), falls back to a minimal contract derived from `mode` alone —
105| * still real (not fabricated data), just lower-confidence, and `ambiguity.reason` says so.
106| */
107|export const resolveTaskContract = (params: {
108|  taskId: string;
109|  rawUserRequest: string;
110|  mode: AgentMode;
111|  routing?: AssistantRequestRouting;
112|}): TaskContract => {
113|  const { taskId, rawUserRequest, mode, routing } = params;
114|  const taskClass = routing
115|    ? mapRequestClassToTaskClass(routing.requestClass)
116|    : (mode === 'agent' ? 'ENGINEERING_CHANGE' : mode === 'plan' ? 'ENGINEERING_QUERY' : 'GENERAL_CHAT');
117|
118|  return {
119|    taskContractId: randomUUID(),
120|    revision: 1,"
}
